(() => {
  'use strict';
  const {layers,projects,guides,sources,glossary}=window.EVALS_CONTENT;
  const {types:learningTypes,levels:learningLevels,journey,experiments:experimentMeta}=window.EVALS_LEARNING;
  const $=(s,r=document)=>r.querySelector(s);
  const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const matchesQuery=(text,query)=>{const words=String(text).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);return String(query).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean).every(token=>words.some(word=>word.startsWith(token)));};
  const layerBy=id=>layers.find(l=>l.id===id)||layers[2];
  const projectBy=id=>projects.find(p=>p.id===id);
  const guideBy=id=>guides.find(g=>g.id===id);
  const paths={menu:'M3 6h18M3 12h18M3 18h18',search:'M21 21l-4.4-4.4M19 10.5a8.5 8.5 0 1 1-17 0 8.5 8.5 0 0 1 17 0',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1zm0 0v15',arrow:'M5 12h14m-5-5 5 5-5 5',external:'M7 17 17 7M7 7h10v10',bookmark:'M6 3h12v18l-6-4-6 4V3z',flask:'M9 3h6M10 3v7L4 20c-.4.7 0 1 1 1h14c1 0 1.4-.3 1-1l-6-10V3M8 14h8',file:'M14 2H5v20h14V7l-5-5zm0 0v6h5M8 13h8M8 17h6',download:'M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',copy:'M9 9h12v12H9zM15 9V3H3v12h6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',layers:'m12 3 10 5-10 5L2 8l10-5zM2 12l10 5 10-5M2 16l10 5 10-5',tag:'M3 3h8l10 10-8 8L3 11V3zM7 7h.01',terminal:'m5 7 5 5-5 5M13 17h6',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4z',list:'M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1'};
  const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`;
  const decorate=()=>$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
  let persisted={saved:[],read:[],checks:{}};
  try{const v=JSON.parse(localStorage.getItem('evals-lab-v1'));if(v&&typeof v==='object')persisted={saved:Array.isArray(v.saved)?v.saved:[],read:Array.isArray(v.read)?v.read:[],checks:v.checks&&typeof v.checks==='object'?v.checks:{}};}catch{}
  const writeState=()=>{try{localStorage.setItem('evals-lab-v1',JSON.stringify(persisted));}catch{toast('Browser storage is unavailable; changes last for this visit.');}};
  let overviewLayer='foundation',route='overview',routeID='',filters={query:'',layer:'all',topic:'all'},lastGate=null;
  function toast(message){const box=$('#toast');box.textContent=message;box.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.hidden=true,2900);}
  function download(filename,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Download prepared.');}
  function layerTag(id){const l=layerBy(id);return `<span class="layer-tag" style="--layer-color:var(--${l.color})"><span class="dot"></span>${esc(l.name)}</span>`;}
  function breadcrumb(parts){return `<div class="breadcrumb"><a href="#/overview">Framework</a>${parts.map(p=>`<span aria-hidden="true">/</span>${p.href?`<a href="${p.href}">${esc(p.text)}</a>`:`<span>${esc(p.text)}</span>`}`).join('')}</div>`;}
  function pageTitle(kicker,title,description,tools='',extra=''){return `<header class="page-title ${extra}"><div><div class="eyebrow">${esc(kicker)}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}${extra==='overview-title'?`<div class="hero-start-actions"><a class="button primary" href="#/start">Start here — no prior knowledge ${icon('arrow')}</a></div>`:''}</div>${tools?`<div class="title-tools">${tools}</div>`:''}</header>`;}
  function saveButton(kind,id){const saved=persisted.saved.includes(`${kind}:${id}`);return `<button class="icon-button" data-save="${kind}:${id}" aria-label="${saved?'Unsave':'Save'} ${esc(kind==='project'?projectBy(id)?.title:guideBy(id)?.title)}" aria-pressed="${saved}">${icon('bookmark')}</button>`;}
  const imageDescriptions={hero:'Light passes through five colored glass inspection frames, illustrating evidence checked across the evaluation layers.',foundation:'A curated tray of textured glass samples with selected mint-colored tiles.',definition:'A precision caliper measures a glass block inside an illuminated golden boundary.',measurement:'An optical bench directs orange light through a prism toward detector plates.',protection:'A rose-colored glass shield deflects particles around a protected cube.',authority:'A blue glass checkpoint opens deliberately for one token while others wait.'};
  const projectImageDescriptions={"project-trajectory":"A branching route of connected glass nodes is inspected by a probe at one broken orange junction.","project-shadow":"A central beam splits into a bright serving path and a faint parallel comparison path on an optical bench.","project-judge":"A precision balance compares differently shaped glass responses with a fine calibration dial.","project-gate":"A mechanical pipeline valve stops an amber pulse while a separate blue route remains clear.","project-rag":"Light threads connect a glass answer tile to selected pages of an open archival book, with one unsupported thread left unattached.","project-dpo":"Paired preference tokens circulate through a sculptural feedback loop and emerge as one refined token.","project-significance":"Two colored clouds of glass beads are compared within a transparent uncertainty envelope.","project-fuzzer":"An irregular tool connector is stress-tested by several fine mechanical probes on an isolated test rig.","project-drift":"A scanning head inspects a long sequence of sample beads whose shape and color gradually change.","project-pareto":"A sculptural tradeoff curve carries selected blue and gold blocks while less efficient configurations sit away from it.","project-replay":"One frame is lifted from a physical glass filmstrip for replacement and controlled replay.","project-synthetic":"An illuminated geometric seed produces varied irregular test pieces through a precision fabrication mold.","project-context":"A circular memory carousel moves a glass tile from a crowded active ring to a separate archive spool.","project-contamination":"Two translucent document sheets reveal matching fingerprint-like patterns where training and evaluation material overlap.","project-methodology":"An open research notebook, drafting compass, and reproducible geometric specimen form a methodology still-life."};
  Object.assign(imageDescriptions,projectImageDescriptions);
  function editorialImage(id,{className='',decorative=false,eager=false,sizes='(max-width: 760px) 100vw, 560px'}={}){return `<img class="${className}" src="assets/images/${id}.webp" srcset="assets/images/${id}-small.webp 560w, assets/images/${id}.webp ${id==='hero'?1280:1120}w" sizes="${sizes}" alt="${decorative?'':esc(imageDescriptions[id])}" width="${id==='hero'?1280:1120}" height="${id==='hero'?853:747}" loading="${eager?'eager':'lazy'}" decoding="async"${eager?' fetchpriority="high"':''}>`;}
  function heroImage(){return `<figure class="hero-visual">${editorialImage('hero',{eager:true,sizes:'(max-width: 1050px) 80vw, 440px'})}<figcaption><span>FIVE LAYERS</span> / From evidence to release.</figcaption></figure>`;}
  function articleImage(id,caption){return `<figure class="article-visual">${editorialImage(id,{eager:true,sizes:'(max-width: 760px) 100vw, 900px'})}<figcaption>${esc(caption)}</figcaption></figure>`;}
  function learningBadges(item){const m=item.learning||item;return `<span class="learning-badges"><span class="learning-badge level-${m.difficulty}" data-difficulty="${m.difficulty}">${learningLevels[m.difficulty].label}</span><span class="learning-badge type-badge" data-content-type="${m.type}">${learningTypes[m.type]}</span></span>`;}
  function learningLink(id){const g=guideBy(id),p=projectBy(id),item=g||p;return item?`<a href="#/${g?'guide':'project'}/${id}">${esc(item.title)}</a>`:'';}
  function learningOrientation(item,guideId=''){const m=item.learning||item,l=layerBy(item.layer||m.layer),step=journey.findIndex(s=>s.id===guideId);const place=step>=0?`Beginner path · Step ${step+1} of ${journey.length}`:m.type==='blueprint'?'Build a system':m.type==='methodology'?'Document your methodology':m.type==='experiment'?'Explore a mechanism':'Deepen your knowledge';return `<section class="learning-banner" aria-label="Where this page fits"><div class="learning-banner-top">${learningBadges(item)}${item.minutes?`<span class="learning-duration">About ${item.minutes} min ${m.type==='practice'?'exercise':'read'}</span>`:''}</div><div class="learning-place"><span>Where this fits</span><strong>${place}</strong><a href="#/layer/${l.id}">${l.name} / ${l.short}</a>${step>=0?'<a href="#/start">View the full path →</a>':''}</div><div class="learning-expectations"><div><strong>${m.type==='blueprint'?'What you will build':m.type==='methodology'?'What you will produce':'What you will learn'}</strong><p>${esc(m.outcome)}</p></div><div><strong>Before this page</strong><p>${m.prerequisites?.length?m.prerequisites.map(learningLink).join(' · '):'No prior AI evaluation knowledge is needed.'}</p></div></div>${m.type==='blueprint'?'<p class="learning-assumption">This is an implementation plan. The concept lessons come first; building the system may require coding and access to your own tools or infrastructure.</p>':''}${m.assumes?`<p class="learning-assumption"><strong>Also assumes:</strong> ${esc(m.assumes)}</p>`:''}${m.terms?.length?`<details class="learning-terms"><summary>Terms used on this page</summary><ul>${m.terms.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}</section>`;}
  function learningNavigation(g){const index=journey.findIndex(s=>s.id===g.id);const next=index>=0&&index<journey.length-1?journey[index+1].id:g.learning.next;const previous=index>0?journey[index-1].id:null;const last=index===journey.length-1;return `<nav class="lesson-navigation" aria-label="Suggested learning sequence"><div><span class="eyebrow">${last?'FOUNDATION PATH COMPLETE':index>=0?'NEXT IN THE BEGINNER PATH':'SUGGESTED NEXT'}</span><h3>${last?'Choose your next direction':esc((guideBy(next)||projectBy(next))?.title||'Explore the framework')}</h3><p>${last?'Continue with retrieval-based answers, agents, or an evaluation specification.':index>=0?'Continue when you can explain the learning outcome above.':'This is a suggested connection; you can return to the learning path at any time.'}</p></div><div class="lesson-actions">${previous?`<a class="text-link" href="#/guide/${previous}">← Previous lesson</a>`:''}${index>=0?`<button class="button primary" data-complete-lesson="${g.id}" data-next-lesson="${last?'start':next}">${last?'Mark complete & choose next':'Mark complete & continue'} ${icon('arrow')}</button>`:`<a class="button primary" href="#/${guideBy(next)?'guide':'project'}/${next}">Continue learning ${icon('arrow')}</a>`}<a class="text-link" href="#/start">View the learning journey</a></div></nav>`;}
  function exerciseWorksheet(g){return `<section class="first-exercise" aria-label="Worked evaluation exercise"><div class="eyebrow">PRACTICE / CONSTRUCTED EXAMPLE</div><h2>Try the five-case evaluation</h2><div class="exercise-policy"><strong>The fictional policy</strong><p>${esc(g.exercise.policy)}</p></div><p>Pass only if the answer follows the policy, handles missing information, and stays within the assistant’s role. Decide “pass” or “fail” and write the evidence for each verdict. Download the blank worksheet if you want to work outside the website.</p><div class="exercise-cases">${g.exercise.cases.map(c=>`<article><span class="eyebrow">CASE ${c.id}</span><h3>${esc(c.input)}</h3><p><strong>Constructed assistant answer:</strong> ${esc(c.answer)}</p></article>`).join('')}</div><button class="button" data-download-first-eval>${icon('download')}Download blank worksheet</button><details class="worked-solution"><summary>Compare your grading with the worked solution</summary>${g.exercise.cases.map(c=>`<article><strong>Case ${c.id} · ${c.verdict}</strong><p>${esc(c.reason)}</p><p><strong>Expected behavior:</strong> ${esc(c.expected)}</p></article>`).join('')}<p><strong>Result:</strong> 2 of 5 pass in this constructed exercise. The sample illustrates a method; it is not evidence that any real system is ready for release.</p></details></section>`;}
  function startPage(){const done=journey.filter(s=>persisted.read.includes(s.id)).length;const next=journey.find(s=>!persisted.read.includes(s.id))?.id||'first-eval-practice';return `${breadcrumb([{text:'Start here'}])}${pageTitle('YOUR FIRST AI EVALUATION','Start with the idea.<br><span class="title-accent">Finish with a small evaluation.</span>','An AI evaluation is a repeatable test of whether an AI system does the job you want. This path assumes no previous eval experience and needs no coding.')}<section class="path-welcome"><div><div class="eyebrow">BEGINNER / SEVEN SHORT LESSONS</div><h2>One example, from question to decision.</h2><p>Follow a fictional returns assistant through the basics. You will define success, choose test cases, grade answers, inspect failures, and write a next-action plan. The lesson order is your learning sequence; the layer names show where each topic belongs in the framework.</p><p class="path-duration">Allow about an hour, including a short practice exercise. You can stop and return at any time.</p></div><div class="path-progress"><strong>${done} of ${journey.length} lessons marked complete</strong><p>Personal reading progress, saved in this browser.</p><a class="button primary" href="#/guide/${next}">${done===journey.length?'Review the practice exercise':done?'Continue the path':'Begin lesson 1'} ${icon('arrow')}</a></div></section><ol class="journey-list">${journey.map((step,i)=>{const g=guideBy(step.id),read=persisted.read.includes(g.id);return `<li class="${read?'lesson-done':''}"><span class="journey-number">${read?'✓':String(i+1).padStart(2,'0')}</span><div><div class="journey-meta">${learningBadges(g)}<span>${g.minutes} min</span><a href="#/layer/${g.layer}">${layerBy(g.layer).name}</a></div><h2><a href="#/guide/${g.id}">${esc(g.title)}</a></h2><p>${esc(step.goal)}</p><a class="text-link" href="#/guide/${g.id}">${read?'Review lesson':'Open lesson'} ${icon('arrow')}</a></div></li>`;}).join('')}</ol><div class="section-head"><h2>After the beginner path</h2></div><p class="section-description">The five layers describe the whole practice. Difficulty describes the knowledge a page assumes. Completing the path prepares you to choose a next topic; it does not certify production readiness.</p><div class="entry-grid"><a class="entry" href="#/guide/rag-evals"><span class="entry-number">DEEPEN / INTERMEDIATE</span><h3>Evaluate answers from documents</h3><p>Learn retrieval-augmented generation (RAG): finding documents and using their evidence to answer.</p>${icon('external')}</a><a class="entry" href="#/guide/agent-evals"><span class="entry-number">DEEPEN / INTERMEDIATE</span><h3>Evaluate an agent’s actions</h3><p>Learn about agents that choose actions and call tools, and inspect the steps they take.</p>${icon('external')}</a><a class="entry" href="#/guide/eval-spec"><span class="entry-number">APPLY / INTERMEDIATE</span><h3>Plan your own evaluation</h3><p>Connect a real task, test cases, grading, and a decision in one evaluation specification.</p>${icon('external')}</a></div><div class="section-head"><h2>How the labels work</h2></div><div class="label-explainer">${Object.entries(learningLevels).map(([id,l])=>`<article><span class="learning-badge level-${id}">${l.label}</span><p>${l.description}</p></article>`).join('')}</div><p class="source-note">Content types tell you what you will do: learn a concept, follow a method, practice on an example, build from a plan, try an experiment, use a template, check readiness, or look up a reference.</p>`;}
  function projectCard(p){return `<article class="project-card"><a class="project-card-main" href="#/project/${p.id}"><div class="project-cover">${editorialImage('project-'+p.id,{decorative:true})}</div><div class="project-card-top">${layerTag(p.layer)}<span class="project-index">P${String(p.number).padStart(2,'0')}</span></div>${learningBadges(p)}<h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p></a><div class="project-card-bottom"><span>${esc(p.topics[0])}</span>${saveButton('project',p.id)}</div></article>`;}
  function guideCard(g){return `<a class="guide-card" href="#/guide/${g.id}">${layerTag(g.layer)}${learningBadges(g)}<h3>${esc(g.title)}</h3><p>${esc(g.summary)}</p><div class="guide-meta"><span>${g.minutes} MIN ${g.learning.type==='practice'?'EXERCISE':'READ'}</span>${persisted.read.includes(g.id)?'<span class="read-progress">✓ READ</span>':`<span>GUIDE ${icon('external')}</span>`}</div></a>`;}
  function sourceLinks(ids){return `<div class="source-links">${ids.map(id=>{const s=sources.find(v=>v.id===id);return s?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${icon('external')}<span>${esc(s.title)}</span><small>${esc(s.publisher)}</small></a>`:'';}).join('')}</div>`;}
  function codeBlock(code,label='ILLUSTRATIVE STARTER'){return `<div class="code-block"><div class="code-head"><span>${esc(label)}</span><button class="icon-button" data-copy-code aria-label="Copy code">${icon('copy')} Copy</button></div><pre><code>${esc(code)}</code></pre></div>`;}
  function sidebar(){const activeLayer=route==='layer'?routeID:route==='project'?projectBy(routeID)?.layer:route==='guide'?guideBy(routeID)?.layer:'';$('#sidebar').innerHTML=`<div class="nav-label">YOUR LEARNING JOURNEY</div><a class="side-item ${route==='start'?'active':''}" href="#/start">${icon('book')}Start here</a><a class="side-item ${route==='overview'?'active':''}" href="#/overview">${icon('grid')}Overview</a><div class="nav-label" style="margin-top:25px">FIVE CONNECTED LAYERS</div>${layers.map((l,i)=>`<a class="side-item ${activeLayer===l.id?'active':''}" href="#/layer/${l.id}" style="--layer-color:var(--${l.color})" ${activeLayer===l.id?'aria-current="page"':''}><span class="dot"></span><span class="side-layer-label"><strong>${l.name}</strong><small>${l.short}</small></span><span class="side-number">0${i+1}</span></a>`).join('')}<hr class="side-divider"><div class="nav-label">IN THE LAB</div><a class="side-item ${['projects','project'].includes(route)?'active':''}" href="#/projects">${icon('terminal')}Project plans<span class="side-number">15</span></a><a class="side-item ${route==='experiments'?'active':''}" href="#/experiments">${icon('flask')}Experiments<span class="side-number">03</span></a><a class="side-item ${['library','guide'].includes(route)?'active':''}" href="#/library">${icon('book')}Guides & resources</a><a class="side-item ${route==='glossary'?'active':''}" href="#/glossary">${icon('list')}Glossary</a><hr class="side-divider"><a class="side-item ${route==='saved'?'active':''}" href="#/saved">${icon('bookmark')}Saved reading<span class="side-number" id="saved-count">${String(persisted.saved.length).padStart(2,'0')}</span></a><div class="side-note">From test data to accountable decisions.<span>A LIVING FIELD GUIDE</span></div>`;$$('[data-top]').forEach(a=>{const key=['project'].includes(route)?'projects':['guide','glossary','saved'].includes(route)?'library':route==='layer'?'overview':route;a.classList.toggle('active',a.dataset.top===key);if(a.dataset.top===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
  function layerMap(){return `<svg class="layer-map" viewBox="0 0 560 285" role="img" aria-labelledby="layer-map-title"><title id="layer-map-title">Five nested evaluation layers, from Foundation at the center to Authority on the outside</title><path class="baseline" d="M25 270H535"/>${[...layers].reverse().map(l=>{const i=layers.indexOf(l),r=53+i*47;return `<path class="arc ${l.id===overviewLayer?'selected':''}" data-map-layer="${l.id}" style="--layer-color:var(--${l.color})" d="M${280-r} 270 A${r} ${r} 0 0 1 ${280+r} 270"/><text class="${l.id===overviewLayer?'selected':''}" data-map-label="${l.id}" x="280" y="${270-r-10}" text-anchor="middle">0${i+1} · ${l.name}</text>`;}).join('')}</svg>`;}
  function overviewDetail(){const l=layerBy(overviewLayer),i=layers.indexOf(l);return `<div class="eyebrow">LAYER 0${i+1} / ${l.name.toUpperCase()}</div><h2>${l.headline}</h2><p>${l.description}</p><p class="layer-question">${l.question}</p><a class="text-link" href="#/layer/${l.id}">Explore this layer ${icon('arrow')}</a>`;}
  function overview(){return `${breadcrumb([{text:'Overview'}])}${pageTitle('NEW TO AI EVALS? YOU ARE IN THE RIGHT PLACE.','Learn to evaluate AI.<br><span class="title-accent">Start with a simple test.</span>','AI evaluations (“evals”) are repeatable tests of whether an AI system does the job you want. Learn the basics here, then explore methods and implementation plans.',heroImage(),'overview-title')}<section class="beginner-start"><div><span class="eyebrow">START HERE / BEGINNER / NO CODING NEEDED</span><h2>Never run an eval before?</h2><p>Follow seven short lessons and grade a fictional returns assistant. Finish with test cases, clear verdicts, and a next-action plan.</p></div><div class="beginner-start-actions"><a class="button primary" href="#/start">Start the beginner path ${icon('arrow')}</a><a class="text-link" href="#/guide/first-eval">First: what is an AI eval?</a></div></section><div class="section-head"><h2>The five layers you will learn</h2><a class="text-link" href="#/start">See the learning order ${icon('arrow')}</a></div><section class="framework-panel" aria-label="Explore the five evaluation layers"><div class="map-side"><div class="map-top"><span class="eyebrow">THE FIVE-LAYER FRAMEWORK</span><span>SELECT A LAYER TO EXPLORE</span></div>${layerMap()}<div class="map-axis"><span>Evidence at the foundation</span><span>Accountability at every layer</span></div><div class="layer-selector" aria-label="Selected framework layer">${layers.map(l=>`<button data-select-layer="${l.id}" aria-pressed="${l.id===overviewLayer}" style="--layer-color:var(--${l.color})"><span class="dot"></span>${l.name}</button>`).join('')}</div></div><div class="layer-detail" id="layer-detail" style="--layer-color:var(--${layerBy(overviewLayer).color})" aria-live="polite">${overviewDetail()}</div></section><div class="section-head"><h2>Beyond the beginner path</h2><span class="eyebrow">CHOOSE A PURPOSE</span></div><div class="entry-grid"><a class="entry" href="#/layer/foundation"><span class="entry-number">01</span><h3>Understand a topic</h3><p>Use the layer chapters to explore concepts and methods at a clearly labeled level.</p>${icon('external')}</a><a class="entry" href="#/projects"><span class="entry-number">02</span><h3>Plan an implementation</h3><p>Follow intermediate and advanced engineering plans after learning their prerequisites.</p>${icon('external')}</a><a class="entry" href="#/experiments"><span class="entry-number">03</span><h3>Try an experiment</h3><p>Explore a controlled example. Each experiment names its level and the concepts to learn first.</p>${icon('external')}</a></div><div class="section-head"><h2>Ready to build? Explore the plans</h2><a class="text-link" href="#/projects">All 15 plans ${icon('arrow')}</a></div><div class="project-grid">${[projectBy('trajectory'),projectBy('judge')].map(projectCard).join('')}</div><div class="section-head"><h2>The whole practice, connected</h2></div><div class="topic-row">${['Models & prompts','RAG','Agents & tools','Multimodal','Cost & latency','Release & operations'].map(t=>`<a class="topic-chip" href="#/projects?topic=${encodeURIComponent(t)}">${esc(t)}</a>`).join('')}</div><div class="quiet-band"><p><strong>More than a score.</strong> The layers connect datasets, criteria, measurement, protection, and accountable decisions. Projects can span several layers.</p><a class="text-link" href="#/library">Explore the reading library ${icon('arrow')}</a></div>`;}
  function layerPage(id){const l=layers.find(x=>x.id===id);if(!l)return notFound();const index=layers.indexOf(l),next=layers[(index+1)%layers.length];const related=projects.filter(p=>p.layer===id||p.also.includes(id));return `${breadcrumb([{text:`Layer 0${index+1}`},{text:l.name}])}<div style="--layer-color:var(--${l.color})">${pageTitle(`LAYER 0${index+1} / ${l.short.toUpperCase()}`,l.headline,l.question,`<button class="button" data-download-layer="${id}">${icon('download')} Layer checklist</button>`)}<div class="chapter-learning-note"><span class="learning-badge type-badge">Layer overview</span><p>This chapter contains beginner lessons and deeper implementation plans. Start with a concept lesson; each item shows its own level and prerequisites.</p><a class="text-link" href="#/start">Find your place in the learning path ${icon('arrow')}</a></div><section class="layer-feature" aria-label="${l.name} introduction"><figure>${editorialImage(l.id,{eager:true})}</figure><p class="layer-intro">${esc(l.intro)}</p></section><div class="layer-outcomes"><section class="outcome"><h3>What this layer establishes</h3><ul>${l.outcomes.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></section><section class="outcome"><h3>The evidence you produce</h3><ul>${l.artifacts.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></section></div><div class="scope-line">Typical ownership: <span>${esc(l.roles)}</span></div><div class="section-head"><h2>Learn the concepts and methods</h2><span class="eyebrow">CONCEPT → PRACTICE</span></div><div class="guide-grid">${guides.filter(g=>g.layer===id).map(guideCard).join('')}</div><div class="section-head"><h2>Implementation plans</h2><span class="eyebrow">${related.length} CONNECTED PROJECTS</span></div><div class="project-grid">${related.map(projectCard).join('')}</div><div class="section-head"><h2>Check an actual implementation</h2><span class="eyebrow">INTERMEDIATE / READINESS CHECKLIST</span></div><p class="section-description">Use this operational checklist when you have a system or evidence package to review. It is separate from completing the beginner lessons.</p>${checklist(l)}<p class="progress-note" id="check-progress">${checkCount(l)} of ${l.checks.length} checked. This personal checklist does not grant release approval.</p><div class="section-head"><h2>Further reading</h2></div>${sourceLinks(l.sources)}<div class="layer-next"><div><div class="eyebrow">${index===4?'RETURN TO THE FOUNDATION':'CONTINUE THROUGH THE FRAMEWORK'}</div><h3>${next.name} — ${next.short}</h3></div><a class="button" href="#/layer/${next.id}">Explore ${next.name.toLowerCase()} ${icon('arrow')}</a></div></div>`;}
  function checkCount(l){return l.checks.filter((_,i)=>persisted.checks[`${l.id}:${i}`]).length;}
  function checklist(l){return `<div class="checklist">${l.checks.map((text,i)=>`<label><input type="checkbox" data-check="${l.id}:${i}" ${persisted.checks[`${l.id}:${i}`]?'checked':''}><span>${esc(text)}</span></label>`).join('')}</div>`;}
  const allTopics=()=>[...new Set(projects.flatMap(p=>p.topics))].sort();
  function projectsPage(params){filters={query:params.get('q')||'',layer:params.get('layer')||'all',topic:params.get('topic')||'all',difficulty:params.get('difficulty')||'all'};return `${breadcrumb([{text:'Project plans'}])}${pageTitle('APPLY YOUR KNOWLEDGE','Choose a system to build.','These fifteen engineering and methodology plans assume you know the basics of test cases, grading, and evaluation design. Each plan names its prerequisites and the evidence it should produce.')}<p class="library-filter-help">New to the subject? <a href="#/start">Follow the beginner path first.</a> A reading level is not an estimate of engineering effort.</p><div class="filterbar"><div class="input-with-icon">${icon('search')}<label class="sr-only" for="project-query">Search implementation plans</label><input class="field" id="project-query" type="search" placeholder="Find a project or failure mode…" value="${esc(filters.query)}"></div><label>Layer<select class="field" id="project-layer"><option value="all">All layers</option>${layers.map(l=>`<option value="${l.id}" ${filters.layer===l.id?'selected':''}>${l.name}</option>`).join('')}</select></label><label>Topic<select class="field" id="project-topic"><option value="all">All topics</option>${allTopics().map(t=>`<option value="${esc(t)}" ${filters.topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Knowledge level<select class="field" id="project-difficulty"><option value="all">All plan levels</option>${['intermediate','advanced'].map(id=>`<option value="${id}" ${filters.difficulty===id?'selected':''}>${learningLevels[id].label}</option>`).join('')}</select></label><span class="count" id="project-count" aria-live="polite"></span></div><div class="project-grid" id="project-grid"></div><div class="quiet-band"><p><strong>What a project plan provides.</strong> An approach, inputs, outputs, measurements, and an illustrative starter. It does not run a production system for you.</p><a class="text-link" href="#/experiments">Try a smaller experiment ${icon('arrow')}</a></div>`;}
  function filterProjects(){const q=filters.query.toLowerCase().trim();const matches=projects.filter(p=>(filters.layer==='all'||p.layer===filters.layer||p.also.includes(filters.layer))&&(filters.topic==='all'||p.topics.includes(filters.topic))&&(!filters.difficulty||filters.difficulty==='all'||p.learning.difficulty===filters.difficulty)&&matchesQuery(`${p.title} ${p.summary} ${p.why} ${p.topics.join(' ')}`,q));$('#project-grid').innerHTML=matches.length?matches.map(projectCard).join(''):`<div class="empty-state"><h2>No projects match those filters.</h2><p>Try a broader topic or search term.</p><button class="button" data-clear-projects>Clear filters</button></div>`;$('#project-count').textContent=`${matches.length} / 15 PROJECTS`;}
  function projectPage(id){const p=projectBy(id);if(!p)return notFound();const l=layerBy(p.layer);const body=p.steps.map(s=>`<li>${esc(s)}</li>`).join('');return `${breadcrumb([{text:'Projects',href:'#/projects'},{text:`P${String(p.number).padStart(2,'0')}`}])}<div style="--layer-color:var(--${l.color})">${pageTitle(`${l.name.toUpperCase()} / ${learningTypes[p.learning.type].toUpperCase()}`,esc(p.title),esc(p.summary),'','article-title')}${learningOrientation(p)}${articleImage('project-'+p.id,p.title)}<div class="reading-meta"><span>P${String(p.number).padStart(2,'0')}</span><span>IMPLEMENTATION PLAN</span><span>${esc(p.topics.join(' · '))}</span></div><div class="two-column"><article class="reading-body"><h2 id="why">Why build it</h2><p>${esc(p.why)}</p><h2 id="inputs">What you need</h2><ul>${p.inputs.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h2 id="implementation">Implementation approach</h2><ol class="step-list">${body}</ol><h2 id="evidence">Evidence and acceptance</h2><p>Define a task-specific acceptance policy before relying on this system. Useful outputs include:</p><div class="artifact-list">${p.outputs.map(s=>`<div class="artifact">${icon('file')}${esc(s)}</div>`).join('')}</div><h3>Measurements to consider</h3><ul>${p.metrics.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><div class="callout"><strong>Interpretation matters</strong><p>${esc(p.caveat)}</p></div><h2 id="starter">An implementation starting point</h2><p>This excerpt illustrates the core idea. It needs the validation, adapters, error handling, and tests appropriate to your environment.</p>${codeBlock(p.code,p.id==='judge'?'JUDGE PROMPT STARTER':'ILLUSTRATIVE STARTER')}<h2 id="references">Further reading</h2>${sourceLinks(p.sources)}<p class="source-note">The blueprint is original Evals Lab guidance based on the supplied project concept. References provide background; they do not certify this implementation.</p><div class="section-head"><h2>Keep building</h2></div><div class="project-grid">${projects.filter(x=>x.id!==p.id&&(x.layer===p.layer||p.also.includes(x.layer))).slice(0,2).map(projectCard).join('')}</div></article><aside class="reading-aside"><div class="eyebrow">IN THIS BLUEPRINT</div><ul><li><a href="#why" data-scroll="why">Why build it</a></li><li><a href="#inputs" data-scroll="inputs">What you need</a></li><li><a href="#implementation" data-scroll="implementation">Implementation</a></li><li><a href="#evidence" data-scroll="evidence">Evidence and acceptance</a></li><li><a href="#starter" data-scroll="starter">Starting point</a></li></ul><div class="aside-layer">${[p.layer,...p.also].map(x=>`<a class="topic-chip" href="#/layer/${x}">${layerBy(x).name}</a>`).join('')}</div><button class="button" data-save="project:${id}" aria-pressed="${persisted.saved.includes(`project:${id}`)}">${icon('bookmark')}<span>${persisted.saved.includes(`project:${id}`)?'Saved to reading':'Save blueprint'}</span></button><button class="button primary" data-download-project="${id}">${icon('download')}Download plan</button><div class="aside-stat"><b>From concept to system</b>Download includes the approach, evidence checklist, and illustrative starter.</div></aside></div></div>`;}
  function guidePage(id){const g=guideBy(id);if(!g)return notFound();const l=layerBy(g.layer),read=persisted.read.includes(id);return `${breadcrumb([{text:'Library',href:'#/library'},{text:l.name}])}<div style="--layer-color:var(--${l.color})">${pageTitle(`${l.name.toUpperCase()} / ${learningTypes[g.learning.type].toUpperCase()}`,esc(g.title),esc(g.summary),'','article-title')}${learningOrientation(g,g.id)}<div class="two-column"><article class="reading-body">${g.exercise?exerciseWorksheet(g):''}${g.sections.map((s,i)=>`<h2 id="section-${i}">${esc(s.heading)}</h2><p>${esc(s.text)}</p>${s.bullets?`<ul>${s.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>`:''}`).join('')}<div class="callout"><strong>Connect the concept to practice</strong><p>Use this guide to define a concrete artifact, the person who owns it, and the evidence that would change your decision. Explore the connected blueprints below.</p></div>${g.sources.length?`<h2>Further reading</h2>${sourceLinks(g.sources)}`:''}${learningNavigation(g)}${g.related.length?`<div class="section-head"><h2>Related implementation plans</h2></div><div class="project-grid">${g.related.map(projectBy).filter(Boolean).map(projectCard).join('')}</div>`:''}</article><aside class="reading-aside"><div class="eyebrow">IN THIS GUIDE</div><ul>${g.sections.map((s,i)=>`<li><a href="#section-${i}" data-scroll="section-${i}">${esc(s.heading)}</a></li>`).join('')}</ul><a class="button" href="#/layer/${g.layer}">${icon('layers')}${l.name} layer</a><button class="button" data-save="guide:${id}" aria-pressed="${persisted.saved.includes(`guide:${id}`)}">${icon('bookmark')}<span>${persisted.saved.includes(`guide:${id}`)?'Saved to reading':'Save guide'}</span></button><button class="button ${read?'':'primary'}" data-read="${id}" aria-pressed="${read}">${icon('check')}<span>${read?'Marked as read':'Mark as read'}</span></button><p class="progress-note">Reading progress is stored in this browser.</p></aside></div></div>`;}
  function libraryPage(){return `${breadcrumb([{text:'Guides & resources'}])}${pageTitle('LEARN / APPLY / LOOK UP','Find the right next resource.','Choose by what you want to do and the knowledge a page assumes. If you are completely new, follow the beginner path before choosing an implementation plan.')}<div class="chapter-learning-note"><a class="button primary" href="#/start">New to evals? Start here ${icon('arrow')}</a><p><strong>Level</strong> tells you what knowledge is assumed. <strong>Content type</strong> tells you whether you will learn a concept, follow a method, or practice on an example.</p></div><div class="section-head"><h2>Lessons and practical guides</h2><span class="eyebrow">${guides.length} RESOURCES / FIVE LAYERS</span></div><div class="filterbar"><label>Knowledge level<select class="field" id="library-level"><option value="all">All levels</option>${Object.entries(learningLevels).map(([id,l])=>`<option value="${id}">${l.label}</option>`).join('')}</select></label><label>Content type<select class="field" id="library-type"><option value="all">All lesson types</option>${['concept','howto','practice'].map(id=>`<option value="${id}">${learningTypes[id]}</option>`).join('')}</select></label><span class="count" id="library-count" aria-live="polite"></span></div><div id="library-guides"></div><div class="section-head"><h2>Produce an evaluation artifact</h2><span class="eyebrow">REUSABLE TEMPLATES</span></div><p class="section-description">Use these when you are ready to document your own system. They are templates to adapt, rather than introductory lessons.</p><div class="template-grid">${[{id:'spec',title:'Evaluation specification',copy:'Record the task, dataset, graders, decision criteria, and ownership.',format:'JSON'},{id:'judge',title:'Judge rubric & prompt',copy:'Adapt a grading prompt and plan how to check its judgments.',format:'MD'},{id:'release',title:'Release evidence checklist',copy:'Record candidate versions, acceptance criteria, exceptions, and rollback.',format:'MD'}].map(t=>`<article class="template"><span class="eyebrow">${t.format} DOWNLOAD</span>${learningBadges({difficulty:'intermediate',type:'template'})}<h3>${t.title}</h3><p>${t.copy}</p><button class="button" data-download-template="${t.id}">${icon('download')}Download template</button></article>`).join('')}</div><div class="section-head"><h2>Go to the original sources</h2><span class="eyebrow">FURTHER READING / REFERENCE</span></div><p class="section-description">These references deepen the site’s explanations. They are not the recommended starting point for someone new to AI evals.</p><div class="resource-list">${sources.map(item=>`<article class="resource"><div class="resource-meta">${esc(item.publisher)} / ${esc(item.type)}</div>${learningBadges(item)}<h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><a class="text-link" href="${item.url}" target="_blank" rel="noopener noreferrer">Read the original ${icon('external')}</a></article>`).join('')}</div><div class="quiet-band"><p><strong>Editorial approach.</strong> Levels describe assumed knowledge, not the importance of a topic or the time needed to build a system. The five-layer structure is our organizing model. Original resource links were checked November 5, 2026.</p><a class="text-link" href="#/glossary">Look up a term ${icon('arrow')}</a></div>`;}
  function filterLibrary(){const level=$('#library-level').value,type=$('#library-type').value;const matches=guides.filter(g=>(level==='all'||g.learning.difficulty===level)&&(type==='all'||g.learning.type===type));$('#library-count').textContent=`${matches.length} / ${guides.length} RESOURCES`;$('#library-guides').innerHTML=matches.length?layers.map(l=>{const group=matches.filter(g=>g.layer===l.id);return group.length?`<div class="section-head"><a class="text-link" href="#/layer/${l.id}">${layerTag(l.id)} ${icon('arrow')}</a></div><div class="guide-grid">${group.map(guideCard).join('')}</div>`:'';}).join(''):`<div class="empty-state"><h2>No lessons match those labels.</h2><p>Advanced material is available in the implementation plans and primary references.</p><a class="button" href="#/projects?difficulty=advanced" style="margin-top:16px">Browse advanced plans ${icon('arrow')}</a></div>`;}
  function glossaryPage(){return `${breadcrumb([{text:'Glossary'}])}${pageTitle('BEGINNER / REFERENCE','Make the terms precise.','Short definitions for the concepts you will encounter across the lab.')}<div class="filterbar"><div class="input-with-icon">${icon('search')}<label class="sr-only" for="glossary-query">Filter glossary</label><input class="field" id="glossary-query" type="search" placeholder="Find a term…"></div><span class="count" id="glossary-count" aria-live="polite"></span></div><dl id="glossary-list"></dl>`;}
  function filterGlossary(q=''){const list=glossary.filter(t=>`${t[0]} ${t[1]}`.toLowerCase().includes(q.toLowerCase()));$('#glossary-list').innerHTML=list.map(t=>`<div class="term"><dt><a href="#/layer/${t[2]}">${esc(t[0])}</a></dt><dd>${esc(t[1])}</dd></div>`).join('')||'<div class="empty-state">No matching terms. Try a shorter search.</div>';$('#glossary-count').textContent=`${list.length} TERMS`;}
  function savedPage(){const items=persisted.saved.map(key=>{const[k,id]=key.split(':');return k==='project'?projectBy(id):guideBy(id);}).filter(Boolean);return `${breadcrumb([{text:'Saved reading'}])}${pageTitle('YOUR READING LIST','Keep the useful ideas close.','Save project blueprints and guides as you explore. Your reading list and checklists are stored in this browser.')}<div class="project-grid">${items.length?persisted.saved.map(key=>{const[k,id]=key.split(':');const item=k==='project'?projectBy(id):guideBy(id);return item?(k==='project'?projectCard(item):guideCard(item)):'';}).join(''):`<div class="empty-state"><h2>Your reading list starts here.</h2><p>Use the bookmark button on a project or guide to keep it here.</p><a class="button" style="margin-top:16px" href="#/projects">Explore the projects ${icon('arrow')}</a></div>`}</div>`;}
  function experimentsPage(id='judge'){const selected=['trace','judge','gate'].includes(id)?id:'judge';return `${breadcrumb([{text:'Experiments'}])}${pageTitle('LEARN BY INSPECTING','Small experiments. Useful questions.','Change a condition, inspect what happens, and connect the result to an evaluation decision. All examples run locally in your browser.')}${learningOrientation({...experimentMeta[selected],learning:experimentMeta[selected]})}<nav class="tabs" aria-label="Experiments">${[['judge','Judge bias'],['trace','Trajectory grading'],['gate','Release gate']].map(([key,title])=>`<a href="#/experiments/${key}" class="${selected===key?'active':''}" ${selected===key?'aria-current="page"':''}>${title}</a>`).join('')}</nav>${selected==='trace'?traceExperiment():selected==='judge'?judgeExperiment():gateExperiment()}<div class="quiet-band"><p><strong>A controlled illustration.</strong> These experiments use constructed examples and simple rules. They explain a mechanism; they do not benchmark a model or operate a production system.</p><a class="text-link" href="#/project/${selected==='trace'?'trajectory':selected==='judge'?'judge':'gate'}">Read the full blueprint ${icon('arrow')}</a></div>`;}
  function traceExperiment(){return `<section class="experiment-panel"><div class="experiment-head"><h2>A good answer can hide a broken step.</h2><span class="demo-label">ILLUSTRATIVE SIMULATION</span></div><p class="experiment-desc">A refund agent must look up an order, verify the policy, and use only valid tool parameters. The grader checks the recorded events against those rules.</p><div class="experiment-content"><div><div class="experiment-controls"><label for="trace-scenario">Scenario</label><select class="field" id="trace-scenario"><option value="unknown">Unknown API parameter</option><option value="missing">Skipped policy check</option><option value="valid">Valid workflow</option><option value="loop">Repeated tool calls</option></select><button class="button primary" id="grade-trace">Grade trace ${icon('arrow')}</button></div><ol class="trace-list" id="trace-list"></ol></div><div class="result-panel" id="trace-result" aria-live="polite"><div class="eyebrow">STEP-LEVEL GRADER</div><h3>Inspect the path, then grade it.</h3><p>The final response says the refund was processed. Can you trust the path that produced it?</p><ul><li>Known tools and allowed parameters</li><li>A policy check before a refund</li><li>A maximum of five tool calls</li></ul></div></div><div class="experiment-note">This deterministic teaching example omits authorization, required-field validation, and actual payment execution. No tool calls or refunds occur.</div></section>`;}
  const traceCases={
    unknown:[['lookup_order',{order_id:'ORD-042'},'Order found'],['verify_policy',{policy_id:'refund-v2'},'Eligible for a refund'],['issue_refund',{order_id:'ORD-042',amount:25,priority:'urgent'},'Unknown parameter: priority']],
    missing:[['lookup_order',{order_id:'ORD-042'},'Order found'],['issue_refund',{order_id:'ORD-042',amount:25},'Policy was not checked']],
    valid:[['lookup_order',{order_id:'ORD-042'},'Order found'],['verify_policy',{policy_id:'refund-v2'},'Eligible for a refund'],['issue_refund',{order_id:'ORD-042',amount:25},'Valid refund action']],
    loop:Array.from({length:6},(_,i)=>['lookup_order',{order_id:'ORD-042'},`Repeated lookup ${i+1}`])
  };
  function traceRows(verdicts=null){const events=traceCases[$('#trace-scenario').value];$('#trace-list').innerHTML=events.map((e,i)=>`<li class="trace-step ${verdicts?.[i]?.status==='fail'?'fail':''}"><span class="trace-num">${String(i+1).padStart(2,'0')}</span><div><code>${esc(e[0])}</code><small>${esc(JSON.stringify(e[1]))}</small></div><span class="status">${verdicts?esc(verdicts[i].status.toUpperCase()):'RECORDED'}</span></li>`).join('');}
  function gradeTrace(){let checked=false,failed=false;const events=traceCases[$('#trace-scenario').value];const schemas={lookup_order:['order_id'],verify_policy:['policy_id'],issue_refund:['order_id','amount']};const results=events.map(([tool,args],i)=>{let reason='Valid schema and prerequisites.';if(i>=5)reason='Tool-call budget exceeded (maximum: 5).';else if(Object.keys(args).some(k=>!schemas[tool].includes(k)))reason='Unknown parameter: '+Object.keys(args).find(k=>!schemas[tool].includes(k))+'.';else if(tool==='issue_refund'&&!checked)reason='Required policy verification is missing.';if(tool==='verify_policy')checked=true;const fail=reason!=='Valid schema and prerequisites.';failed ||= fail;return {status:fail?'fail':'pass',reason};});traceRows(results);const first=results.findIndex(v=>v.status==='fail');$('#trace-result').innerHTML=`<div class="eyebrow">${failed?'FIRST VIOLATION / STEP '+String(first+1).padStart(2,'0'):'ALL RECORDED STEPS CHECKED'}</div><h3 class="${failed?'status-fail':'status-pass'}">${failed?'The trajectory fails.':'The trajectory passes these checks.'}</h3><p>${failed?esc(results[first].reason):'All recorded calls satisfy the three example rules. This does not establish that every real-world safety or task requirement is met.'}</p><div class="gate-check"><span>Passing steps</span><span>${results.filter(v=>v.status==='pass').length} / ${results.length}</span></div><p style="margin-top:15px">${failed?'A fluent final answer does not override an invalid action. Inspect the earliest broken constraint before changing the final response.':'Combine this process check with an independent check that the intended environment outcome actually occurred.'}</p>`;}
  const anchors=[{id:'A01',winner:'A',longer:'A',criterion:'Complete and supported'},{id:'A02',winner:'B',longer:'A',criterion:'Correct core answer'},{id:'A03',winner:'B',longer:'B',criterion:'Uses supplied evidence'},{id:'A04',winner:'A',longer:'B',criterion:'Follows the task'},{id:'A05',winner:'A',longer:'B',criterion:'Handles missing evidence'},{id:'A06',winner:'B',longer:'A',criterion:'Satisfies all constraints'}];
  function judgeExperiment(){return `<section class="experiment-panel"><div class="experiment-head"><h2>Evaluate the judge before trusting the score.</h2><span class="demo-label">CONSTRUCTED ANCHORS</span></div><p class="experiment-desc">An anchor is an example with a known human judgment. These six teaching anchors have fixed human preferences. Compare three simplified judging rules, then swap the answer order to reveal a position effect.</p><div class="experiment-content"><div><div class="experiment-controls"><label for="judge-rule">Judge rule</label><select class="field" id="judge-rule"><option value="position">Always choose the first answer</option><option value="verbosity">Always choose the longer answer</option><option value="rubric">Use the rubric (one fixed error)</option></select></div><table class="data-table"><caption>Human preferences and simulated judgments</caption><thead><tr><th>Anchor</th><th>Human</th><th>A first</th><th>B first</th></tr></thead><tbody id="judge-table"></tbody></table></div><div class="result-panel" id="judge-result" aria-live="polite"></div></div><div class="experiment-note">The anchor labels and judge outputs are constructed for teaching. No LLM is called. Real calibration requires independent labels, held-out examples, and uncertainty analysis.</div></section>`;}
  function updateJudge(){const rule=$('#judge-rule').value;const data=anchors.map((a,i)=>{const decision=rule==='position'?'A':rule==='verbosity'?a.longer:i===4?'B':a.winner;const swapped=rule==='position'?'B':decision;return {...a,decision,swapped};});$('#judge-table').innerHTML=data.map(a=>`<tr><td><span title="${a.criterion}">${a.id}</span></td><td>${a.winner}</td><td class="${a.decision===a.winner?'status-pass':'status-fail'}">${a.decision}</td><td class="${a.swapped===a.winner?'status-pass':'status-fail'}">${a.swapped}</td></tr>`).join('');const agree=data.filter(a=>a.decision===a.winner).length,flip=data.filter(a=>a.decision!==a.swapped).length,after=data.filter(a=>a.swapped===a.winner).length;$('#judge-result').innerHTML=`<div class="eyebrow">AGREEMENT WITH HUMAN ANCHORS</div><div class="metric-display">${Math.round(agree/data.length*100)}<span style="font-size:20px">%</span></div><p>${agree} of ${data.length} judgments match the human preference with A shown first.</p><div class="gate-check"><span>Agreement after order swap</span><span>${after} / ${data.length}</span></div><div class="gate-check" style="margin-top:8px"><span>Preferences that flip</span><span class="${flip?'status-fail':'status-pass'}">${flip} / ${data.length}</span></div><p style="margin-top:16px">${rule==='position'?'Aggregate agreement stays the same after swapping, but every individual preference changes. Aggregate scores can hide a severe position bias.':rule==='verbosity'?'This judge is stable under an order swap, but it still rewards length. One bias check cannot establish overall judge quality.':'This rule is stable and mostly agrees with the anchors, yet it still makes an error. Inspect disagreements and validate on independent held-out cases.'}</p>`;}
  function gateExperiment(){return `<section class="experiment-panel"><div class="experiment-head"><h2>Make the release policy explicit.</h2><span class="demo-label">POLICY SIMULATION</span></div><p class="experiment-desc">Adjust the candidate results and example budgets. The gate checks completeness, minimum paired cases, critical failures, quality change, and latency.</p><form id="gate-form"><div class="experiment-content"><div><div class="gate-fields">${[{id:'baseline',label:'Baseline task success',value:90,min:0,max:100,step:.1,unit:'Percent of tasks'},{id:'candidate',label:'Candidate task success',value:88.5,min:0,max:100,step:.1,unit:'Percent of tasks'},{id:'baseLatency',label:'Baseline p95 latency',value:1200,min:1,max:1000000,step:1,unit:'Milliseconds'},{id:'candidateLatency',label:'Candidate p95 latency',value:1550,min:1,max:1000000,step:1,unit:'Milliseconds'},{id:'drop',label:'Maximum quality drop',value:2,min:0,max:100,step:.1,unit:'Percentage points'},{id:'latency',label:'Maximum latency increase',value:20,min:0,max:10000,step:.1,unit:'Relative percent'},{id:'pairs',label:'Evaluated paired cases',value:200,min:0,max:10000000,step:1,unit:'Example policy minimum: 100'},{id:'critical',label:'Critical failures',value:0,min:0,max:10000000,step:1,unit:'Any critical failure blocks'}].map(f=>`<label for="gate-${f.id}">${f.label}<input class="field" id="gate-${f.id}" name="${f.id}" type="number" value="${f.value}" min="${f.min}" max="${f.max}" step="${f.step}" required><small>${f.unit}</small></label>`).join('')}</div><label style="display:flex;align-items:center;gap:9px;font-size:12px;margin-top:18px;color:var(--muted)"><input type="checkbox" id="gate-complete" checked>All expected cases and graders completed</label><div class="experiment-controls" style="margin:17px 0 0"><button class="button primary" type="submit">Evaluate the policy ${icon('arrow')}</button></div><p class="error-note" id="gate-error" role="alert"></p></div><div class="result-panel" id="gate-result" aria-live="polite"></div></div></form><div class="experiment-note">These thresholds are illustrative. This simplified gate does not model statistical uncertainty, subgroup failures, or the full evidence needed for an actual release decision.</div></section>`;}
  function calculateGate(){const names=['baseline','candidate','baseLatency','candidateLatency','drop','latency','pairs','critical'];const v=Object.fromEntries(names.map(n=>[n,Number($(`#gate-${n}`).value)]));if(names.some(n=>!Number.isFinite(v[n])||$(`#gate-${n}`).value.trim()===''||!$(`#gate-${n}`).checkValidity())){$('#gate-error').textContent='Enter valid numbers within the limits shown.';return;}$('#gate-error').textContent='';const delta=v.candidate-v.baseline,latency=(v.candidateLatency/v.baseLatency-1)*100;const checks=[['Complete evaluation',$('#gate-complete').checked],['At least 100 paired cases',v.pairs>=100],['No critical failures',v.critical===0],[`Quality change: ${delta>=0?'+':''}${delta.toFixed(1)} pp`,delta>=-v.drop],[`p95 latency change: ${latency>=0?'+':''}${latency.toFixed(1)}%`,latency<=v.latency]];const passed=checks.every(c=>c[1]);lastGate={simulation:true,inputs:v,complete:$('#gate-complete').checked,quality_delta_pp:delta,latency_change_percent:latency,passed,checks:checks.map(([label,pass])=>({label,pass})),limitations:['Does not model statistical uncertainty or subgroup failures','Illustrative acceptance policy; not release approval']};$('#gate-result').innerHTML=`<div class="eyebrow">EXAMPLE POLICY RESULT</div><h3 class="${passed?'status-pass':'status-fail'}">${passed?'Passes this policy.':'Release blocked.'}</h3><p>${passed?'The inputs meet all five example checks. A real decision still needs the required evidence and a responsible owner.':'At least one required check fails. Inspect the result and the policy before deciding what to change.'}</p><div class="gate-results">${checks.map(([label,ok])=>`<div class="gate-check"><span>${label}</span><span class="${ok?'status-pass':'status-fail'}">${ok?'PASS':'BLOCK'}</span></div>`).join('')}</div><button type="button" class="button" style="margin-top:19px" data-download-gate>${icon('download')}Download result</button>`;}
  function notFound(){return `${breadcrumb([{text:'Page not found'}])}<div class="empty-state"><h2>That page is not in the lab.</h2><p>Return to the framework or search for a topic.</p><a class="button" href="#/overview" style="margin-top:15px">Back to the overview ${icon('arrow')}</a></div>`;}
  function navigate(){const raw=location.hash.replace(/^#\/?/,'')||'overview';const[path,query='']=raw.split('?');[route,routeID='']=path.split('/');const params=new URLSearchParams(query);const views={overview,start:startPage,layer:()=>layerPage(routeID),projects:()=>projectsPage(params),project:()=>projectPage(routeID),guide:()=>guidePage(routeID),library:libraryPage,glossary:glossaryPage,saved:savedPage,experiments:()=>experimentsPage(routeID)};$('#main').innerHTML=(views[route]||notFound)();sidebar();decorate();document.body.classList.remove('nav-open');$('#menu-button').setAttribute('aria-expanded','false');if($('#search-dialog').open)$('#search-dialog').close();if(route==='projects')filterProjects();if(route==='glossary')filterGlossary();if(route==='library')filterLibrary();if(route==='experiments'){if($('#trace-list'))traceRows();if($('#judge-table'))updateJudge();if($('#gate-result'))calculateGate();}document.title=`${route==='project'?projectBy(routeID)?.title||'Project':route==='guide'?guideBy(routeID)?.title||'Guide':route==='layer'?layerBy(routeID).name:({start:'Start Here — Beginner Learning Path',overview:'From Evidence to Release',projects:'Project Blueprints',library:'Guides & Resources',experiments:'Interactive Experiments',glossary:'Glossary',saved:'Saved Reading'}[route]||'Field Guide')} — Evals Lab`;window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
  function updateLayer(id){overviewLayer=id;const l=layerBy(id);$('#layer-detail').innerHTML=overviewDetail();$('#layer-detail').style.setProperty('--layer-color',`var(--${l.color})`);$$('[data-select-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.selectLayer===id)));$$('[data-map-layer]').forEach(p=>p.classList.toggle('selected',p.dataset.mapLayer===id));$$('[data-map-label]').forEach(p=>p.classList.toggle('selected',p.dataset.mapLabel===id));}
  function saveReading(key){const index=persisted.saved.indexOf(key);if(index>=0)persisted.saved.splice(index,1);else persisted.saved.push(key);writeState();$$('[data-save]').filter(b=>b.dataset.save===key).forEach(b=>{const now=persisted.saved.includes(key);b.setAttribute('aria-pressed',String(now));const span=b.querySelector('span');if(span)span.textContent=now?'Saved to reading':key.startsWith('project')?'Save blueprint':'Save guide';else{const[k,id]=key.split(':');const title=k==='project'?projectBy(id)?.title:guideBy(id)?.title;b.setAttribute('aria-label',`${now?'Unsave':'Save'} ${title}`);}});$('#saved-count').textContent=String(persisted.saved.length).padStart(2,'0');if(route==='saved')navigate();toast(index>=0?'Removed from saved reading.':'Added to saved reading.');}
  const searchIndex=[{title:'Start here: your first AI evaluation',copy:'Beginner learning path. No coding needed. Seven lessons and a worked exercise.',type:'Learning path',layer:'foundation',href:'#/start'},...layers.map(l=>({title:l.name+' — '+l.short,copy:l.description,type:'Layer',layer:l.id,href:`#/layer/${l.id}`})),...guides.map(g=>({title:g.title,copy:g.summary,type:learningLevels[g.learning.difficulty].label+' · '+learningTypes[g.learning.type],layer:g.layer,href:`#/guide/${g.id}`})),...projects.map(p=>({title:p.title,copy:p.summary,type:learningLevels[p.learning.difficulty].label+' · '+learningTypes[p.learning.type],layer:p.layer,href:`#/project/${p.id}`})),...glossary.map(t=>({title:t[0],copy:t[1],type:'Glossary',layer:t[2],href:'#/glossary',term:t[0]}))];
  function search(q=''){const tokens=q.toLowerCase().trim().split(/\s+/).filter(Boolean);let hits=tokens.length?searchIndex.filter(item=>matchesQuery(`${item.title} ${item.copy} ${item.type} ${item.layer}`,q)):searchIndex.filter(x=>['Start here: your first AI evaluation','What is an AI evaluation?','Run your first evaluation without code','Define success before scoring','Golden set'].includes(x.title));$('#search-results').innerHTML=hits.length?hits.slice(0,18).map(x=>`<a class="search-result" href="${x.href}" ${x.term?`data-search-term="${esc(x.term)}"`:''}><span class="dot" style="--layer-color:var(--${layerBy(x.layer).color})"></span><div><div class="eyebrow">${x.type} / ${layerBy(x.layer).name}</div><strong>${esc(x.title)}</strong><p>${esc(x.copy)}</p></div></a>`).join(''):`<div class="empty-state"><h2>No matching topics.</h2><p>Try “judge”, “RAG”, “release”, or “dataset”.</p></div>`;}
  function openSearch(){if(!$('#search-dialog').open)$('#search-dialog').showModal();$('#global-search').value='';search();$('#global-search').focus();}
  const specTemplate=()=>({title:'Your evaluation specification',status:'draft',task:{goal:'',target_population:'',available_evidence:[],forbidden_outcomes:[]},versions:{system:'',model:'',prompt:'',tools:'',dataset:'',grader:''},data:{sampling_unit:'',slices:[],provenance:'',held_out_policy:''},grading:{metrics:[],rubric:'',human_anchors:'',invalid_output_policy:''},comparison:{baseline:'',pairing:'',repetitions:null,uncertainty_method:''},acceptance:{hard_constraints:[],quality_budget:null,latency_budget:null,inconclusive_policy:''},decision:{owner:'',risk_reviewer:'',evidence_required:[],rollback_triggers:[],reapproval_triggers:[]}});
  function templateDownload(id){if(id==='spec')return download('eval-specification.json',JSON.stringify(specTemplate(),null,2),'application/json');if(id==='judge')return download('judge-rubric-starter.md','# Judge rubric starter\n\n'+projectBy('judge').code+'\n\n## Calibration checklist\n- Independent human anchors and adjudication\n- Separate development and held-out validation\n- Blind identities and randomize answer order\n- Test verbosity, position, and attribution effects\n- Inspect disagreements by slice\n- Pin the judge model and prompt version\n');download('release-evidence-checklist.md','# Release evidence checklist\n\n'+layerBy('authority').checks.map(c=>'- [ ] '+c).join('\n')+'\n\n## Sign-off record\n- Candidate versions:\n- Evidence report:\n- Acceptance policy:\n- Critical slice results:\n- Uncertainty and remaining gaps:\n- Decision owner:\n- Residual risk and exceptions:\n- Exception expiration:\n- Rollback triggers:\n- Re-approval triggers:\n\nThis template does not grant approval.\n');}
  function projectDownload(id){const p=projectBy(id);download(`${id}-blueprint.md`,`# ${p.title}\n\n${p.summary}\n\n## Why\n${p.why}\n\n## Inputs\n${p.inputs.map(v=>'- '+v).join('\n')}\n\n## Implementation\n${p.steps.map((v,i)=>(i+1)+'. '+v).join('\n\n')}\n\n## Evidence\n${p.outputs.map(v=>'- '+v).join('\n')}\n\n## Metrics\n${p.metrics.map(v=>'- '+v).join('\n')}\n\n## Interpretation\n${p.caveat}\n\n## Illustrative starter\n\x60\x60\x60\n${p.code}\n\x60\x60\x60\n\n## References\n${p.sources.map(id=>{const s=sources.find(x=>x.id===id);return '- '+s.title+': '+s.url;}).join('\n')}\n`);}
  document.addEventListener('click',async event=>{const el=event.target.closest('button,a');if(!el)return;if(el.classList.contains('search-result')&&!el.dataset.searchTerm)$('#search-dialog').close();if(el.dataset.completeLesson){const id=el.dataset.completeLesson;if(!persisted.read.includes(id))persisted.read.push(id);writeState();location.hash=el.dataset.nextLesson==='start'?'#/start':'#/guide/'+el.dataset.nextLesson;return;}if(el.hasAttribute('data-download-first-eval')){const g=guideBy('first-eval-practice');const rows=[['Case','Question','Constructed answer','Your verdict','Your evidence or reason'],...g.exercise.cases.map(c=>[c.id,c.input,c.answer,'',''])];const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';download('first-evaluation-worksheet.csv',rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');return;}if(el.dataset.selectLayer){updateLayer(el.dataset.selectLayer);return;}if(el.dataset.save){saveReading(el.dataset.save);return;}if(el.dataset.read){const id=el.dataset.read,index=persisted.read.indexOf(id);if(index>=0)persisted.read.splice(index,1);else persisted.read.push(id);writeState();const read=persisted.read.includes(id);el.setAttribute('aria-pressed',String(read));el.classList.toggle('primary',!read);$('span',el).textContent=read?'Marked as read':'Mark as read';toast(read?'Guide marked as read.':'Guide marked as unread.');return;}if(el.hasAttribute('data-copy-code')){const text=$('code',el.closest('.code-block')).textContent;try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{toast('Copy is unavailable. Download the blueprint to keep the example.');}return;}if(el.dataset.scroll){event.preventDefault();const target=document.getElementById(el.dataset.scroll);if(target){if(el.dataset.scroll==='main')target.focus({preventScroll:true});target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}return;}if(el.dataset.downloadProject){projectDownload(el.dataset.downloadProject);return;}if(el.dataset.downloadLayer){const l=layerBy(el.dataset.downloadLayer);download(`${l.id}-checklist.md`,`# ${l.name} — ${l.short}\n\n${l.question}\n\n${l.checks.map(c=>'- [ ] '+c).join('\n')}\n\nOwner: ${l.roles}\n\nEvidence artifacts:\n${l.artifacts.map(c=>'- '+c).join('\n')}\n\nPersonal readiness checklist; not release approval.\n`);return;}if(el.dataset.downloadTemplate){templateDownload(el.dataset.downloadTemplate);return;}if(el.hasAttribute('data-download-gate')){if(lastGate)download('release-gate-simulation.json',JSON.stringify(lastGate,null,2),'application/json');return;}if(el.hasAttribute('data-clear-projects')){filters={query:'',layer:'all',topic:'all',difficulty:'all'};$('#project-difficulty').value='all';$('#project-query').value='';$('#project-layer').value='all';$('#project-topic').value='all';filterProjects();return;}if(el.dataset.searchTerm){const term=el.dataset.searchTerm;$('#search-dialog').close();if(route==='glossary'){$('#glossary-query').value=term;filterGlossary(term);}else{location.hash='#/glossary';setTimeout(()=>{if($('#glossary-query')){$('#glossary-query').value=term;filterGlossary(term);}},0);}return;}if(el.id==='grade-trace')gradeTrace();});
  document.addEventListener('input',event=>{const e=event.target;if(e.id==='project-query'){filters.query=e.value;filterProjects();}if(e.id==='glossary-query')filterGlossary(e.value);if(e.id==='global-search')search(e.value);});
  document.addEventListener('change',event=>{const e=event.target;if(e.id==='project-layer'){filters.layer=e.value;filterProjects();}if(e.id==='project-topic'){filters.topic=e.value;filterProjects();}if(e.id==='project-difficulty'){filters.difficulty=e.value;filterProjects();}if(e.id==='library-level'||e.id==='library-type')filterLibrary();if(e.id==='trace-scenario'){traceRows();$('#trace-result').innerHTML='<div class="eyebrow">SCENARIO CHANGED</div><h3>Ready to inspect.</h3><p>Grade this recorded sequence against the three example constraints.</p>';}if(e.id==='judge-rule')updateJudge();if(e.dataset.check){persisted.checks[e.dataset.check]=e.checked;writeState();const l=layerBy(e.dataset.check.split(':')[0]);$('#check-progress').textContent=`${checkCount(l)} of ${l.checks.length} checked. This personal checklist does not grant release approval.`;}});
  document.addEventListener('submit',event=>{if(event.target.id==='gate-form'){event.preventDefault();calculateGate();}});
  $('#search-button').addEventListener('click',openSearch);$('#close-search').addEventListener('click',()=>$('#search-dialog').close());$('#global-search').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();const result=$('.search-result',$('#search-results'));if(result)result.click();}if(event.key==='ArrowDown'){event.preventDefault();$('.search-result',$('#search-results'))?.focus();}});$('#search-dialog').addEventListener('click',event=>{if(event.target===$('#search-dialog')){const rect=event.target.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)event.target.close();}});
  document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='Escape'){document.body.classList.remove('nav-open');$('#menu-button').setAttribute('aria-expanded','false');}});
  $('#menu-button').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#menu-button').setAttribute('aria-expanded',String(open));});$('#sidebar-shade').addEventListener('click',()=>{document.body.classList.remove('nav-open');$('#menu-button').setAttribute('aria-expanded','false');});
  window.addEventListener('hashchange',navigate);navigate();
})();
